"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["83078"],{468403(n){n.exports=JSON.parse('{"id":11898,"title":"PRD1:\u5168\u5C40\u67B6\u6784\u7EA7 PRD \u4E13\u5C5E\u63D0\u793A\u8BCD","description":"# \u6838\u5FC3\u4EFB\u52A1\\n\u8BF7\u4F5C\u4E3A\u7CFB\u7EDF\u603B\u67B6\u6784\u5E08\uFF0C\u4E3A\u6211\u4EEC\u7684\u5168\u516C\u53F8\u5185\u90E8\u7CFB\u7EDF\u8F93\u51FA\u4E00\u4EFD\u300A\u7CFB\u7EDF\u5168\u5C40\u67B6\u6784\u84DD\u56FE (Master PRD)\u300B\u3002\\n\u8FD9\u4EFD\u6587\u6863\u4E0D\u9700\u8981\u9677\u5165\u5355\u4E2A\u9875\u9762\u7684\u6309\u94AE\u6216 UI \u7EC6\u8282\uFF0C\u800C\u662F\u8981\u5728\u6700\u9AD8\u89C6\u89D2\u628A\u63A7\u5B50\u7CFB\u7EDF\u8FB9\u754C\u3001\u5168\u5C40\u72B6\u6001\u6D41\u8F6C\u3001\u4EE5\u53CA\u8DE8\u90E8\u95E8\u7684\u6570\u636E\u4EA4\u4E92\u89C4\u5219\uFF0C\u4E3A IT \u90E8\u95E8\u63D0\u4F9B\u5E95\u5C42\u6570\u636E\u5E93\u8BBE\u8BA1\u4E0E\u5FAE\u670D\u52A1\u62C6\u5206\u7684\u5168\u5C40\u6307\u5BFC\u3002\\n\\n# \u8F93\u51FA\u7ED3\u6784\u4E0E\u89C4\u8303\\n\u8BF7\u4E25\u683C\u6309\u7167\u4EE5\u4E0B 4 \u4E2A\u6838\u5FC3\u67B6\u6784\u6A21\u5757\u8FDB\u884C\u8F93\u51FA\uFF1A\\n\\n## 1. \u4E1A\u52A1\u5168\u666F\u56FE\u4E0E\u5B50\u7CFB\u7EDF\u8FB9\u754C (System Topography)\\n- \u8BF7\u4F7F\u7528 Mermaid \u6D41\u7A0B\u56FE (Graph TD) \u753B\u51FA\u5168\u516C\u53F8\u7684\u7CFB\u7EDF\u62D3\u6251\u56FE\u3002\\n- \u5FC5\u987B\u660E\u786E\u6807\u51FA\uFF1A\u5916\u90E8\u89E6\u70B9\uFF08\u5982\u524D\u7AEF\u4E1A\u52A1\u6D41\u5165\u70B9\uFF09\u3001\u5185\u90E8\u6838\u5FC3\u5B50\u7CFB\u7EDF\uFF08\u5982\u8BA2\u5355\u4E2D\u5FC3\u3001\u91C7\u8D2D\u8C03\u5EA6\u4E2D\u5FC3\u3001\u8D22\u52A1\u6838\u7B97\u4E2D\u5FC3\uFF09\u4EE5\u53CA\u5B83\u4EEC\u4E4B\u95F4\u7684\u6570\u636E\u6D41\u5411\u4E0E\u6307\u4EE4\u4F9D\u8D56\u5173\u7CFB\u3002\\n\\n## 2. \u5168\u5C40\u6838\u5FC3\u5355\u636E\u4E0E\u72B6\u6001\u673A (Global State Machine)\\n- \u63D0\u53D6\u8D2F\u7A7F\u5168\u516C\u53F8\u4E1A\u52A1\u7EBF\u6700\u6838\u5FC3\u7684 1-2 \u79CD\u5355\u636E\uFF08\u5982\uFF1A\u5168\u5C40\u4E3B\u8BA2\u5355\u3001\u5168\u5C40\u5C65\u7EA6\u5355\uFF09\u3002\\n- \u8BF7\u4F7F\u7528 Mermaid \u72B6\u6001\u56FE (State Diagram) \u7ED8\u5236\u5176\u4ECE\u201C\u751F\u6210\u201D\u5230\u201C\u8D22\u52A1\u7ED3\u7B97/\u4F5C\u5E9F\u201D\u7684\u5168\u751F\u547D\u5468\u671F\u5168\u5C40\u72B6\u6001\u6D41\u8F6C\u3002\\n- \u5728\u72B6\u6001\u673A\u4E0B\u65B9\uFF0C\u4EC5\u5BF9\u6D89\u53CA\u8DE8\u7CFB\u7EDF\u629B\u5355\u3001\u8DE8\u90E8\u95E8\u8D23\u4EFB\u8F6C\u79FB\u7684\u201C\u6838\u5FC3\u67A2\u7EBD\u72B6\u6001\u201D\u8FDB\u884C\u6587\u5B57\u8BF4\u660E\u3002\\n\\n## 3. \u5168\u5C40\u7EC4\u7EC7\u67B6\u6784\u4E0E\u89D2\u8272\u77E9\u9635 (Global RBAC Architecture)\\n- \u68B3\u7406\u8DE8\u90E8\u95E8\u7684\u5168\u5C40\u89D2\u8272\u6C60\uFF08\u5982\uFF1A\u4E1A\u52A1\u7AEF\u64CD\u4F5C\u5458\u3001\u4E1A\u52A1\u7AEF\u7BA1\u7406\u8005\u3001\u8D22\u52A1\u7AEF\u3001\u7CFB\u7EDF\u8D85\u7BA1\uFF09\u3002\\n- \u660E\u786E\u5168\u5C40\u7684\u6570\u636E\u9694\u79BB\u6700\u9AD8\u539F\u5219\uFF08\u4F8B\u5982\uFF1A\u6309\u4E1A\u52A1\u7EBF\u9694\u79BB\u3001\u6309\u90E8\u95E8\u7EC4\u7EC7\u67B6\u6784\u9694\u79BB\uFF0C\u8FD8\u662F\u6309\u7279\u5B9A\u6570\u636E\u6807\u8BC6\u9694\u79BB\uFF09\uFF0C\u6307\u5BFC\u5E95\u5C42\u6570\u636E\u6743\u9650\u8868\u7684\u8BBE\u8BA1\u3002\\n\\n## 4. \u5168\u5C40\u901A\u7528\u5F02\u5E38\u62E6\u622A\u7F51 (Global Exception Handling)\\n- \u7EDF\u4E00\u5B9A\u4E49\u5168\u7CFB\u7EDF\u7684\u901A\u7528\u62A5\u9519\u89C4\u8303\u4E0E\u515C\u5E95\u6D41\u8F6C\u673A\u5236\u3002\\n- \u660E\u786E\u8BF8\u5982\u201C\u63A5\u53E3\u8D85\u65F6\u201D\u3001\u201C\u5E76\u53D1\u51B2\u7A81\u201D\u3001\u201C\u5E95\u5C42\u8D26\u5B9E\u4E0D\u7B26\u201D\u7B49\u5168\u5C40\u7EA7\u5F02\u5E38\u53D1\u751F\u65F6\uFF0C\u7CFB\u7EDF\u7684\u7EDF\u4E00\u6302\u8D77\u89C4\u5219\u53CA\u76D1\u63A7\u62A5\u8B66\u673A\u5236\u3002\\n\\n# \u8F93\u5165\u4FE1\u606F\\n- \u672C\u6B21\u8BBE\u8BA1\u7684\u516C\u53F8\u7EA7\u6838\u5FC3\u4E1A\u52A1\u7EBF\uFF1A[\u586B\u5199\u6838\u5FC3\u4E1A\u52A1\uFF0C\u5982\uFF1A\u7EAF\u76F4\u53D1\u6A21\u5F0F\u4E0B\u7684\u5168\u94FE\u8DEF\u7535\u5546\u5C65\u7EA6\u7CFB\u7EDF]\\n- \u6D89\u53CA\u7684\u6838\u5FC3\u4E1A\u52A1\u90E8\u95E8\uFF1A[\u586B\u5199\u90E8\u95E8\uFF0C\u5982\uFF1A\u8FD0\u8425\u90E8\u3001\u91C7\u8D2D\u90E8\u3001\u8D22\u52A1\u90E8]\\n- \u67B6\u6784\u8BBE\u8BA1\u7684\u6838\u5FC3\u75DB\u70B9/\u76EE\u7684\uFF1A[\u586B\u5199\u9700\u91CD\u70B9\u89E3\u51B3\u7684\u5168\u5C40\u95EE\u9898\uFF0C\u5982\uFF1A\u6D88\u9664\u5404\u4E1A\u52A1\u73AF\u8282\u7684\u4FE1\u606F\u65AD\u5C42\uFF0C\u5B9E\u73B0\u5355\u636E\u6D41\u4E0E\u8D44\u91D1\u6D41\u7684\u4E00\u4E00\u5BF9\u5E94]","owner":"wansgenhao","upvotes":3,"downvotes":0,"upvoteDifference":3,"updatedAt":"2026-04-13T20:39:07.748Z"}')}}]);